import{_ as s,C as i,c as d,o as u,a3 as r,G as a,j as e,a as o}from"./chunks/framework.Dokpd4od.js";const P=JSON.parse('{"title":"Produce and consume","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/manufacturing/workflows/produce-and-consume.md","filePath":"master/supply-chain/manufacturing/workflows/produce-and-consume.md","lastUpdated":1793074831000}'),l={name:"master/supply-chain/manufacturing/workflows/produce-and-consume.md"};function c(h,t,p,g,m,f){const n=i("ImagePopup");return u(),d("div",null,[t[0]||(t[0]=r('<h1 id="produce-and-consume" tabindex="-1">Produce and consume <a class="header-anchor" href="#produce-and-consume" aria-label="Permalink to &quot;Produce and consume&quot;">​</a></h1><p>Producing is the last step of an MO. You tell Aureus how much you made and how much of each component you used. Aureus then removes the components from stock, adds the finished goods and closes the order.</p><blockquote><p><strong>In simple words:</strong> Produce means &quot;I made it&quot;. Consume means &quot;these parts were used up&quot;.</p></blockquote><p>Use the buttons on the MO at <code>Manufacturing → Operations → Manufacturing Orders</code>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>How strict Aureus is about extra or missing components is set on the bill of materials. Open the BoM and look at <strong>Flexible Consumption</strong> in the <strong>Miscellaneous</strong> box. See <a href="./../basic-setup/bill-of-materials.html">Bill of materials</a>.</p><table tabindex="0"><thead><tr><th>Value</th><th>What you see when you produce</th></tr></thead><tbody><tr><td><strong>Allowed</strong></td><td>No warning. Consumed amounts are accepted as typed.</td></tr><tr><td><strong>Allowed with warning</strong></td><td>The <strong>Consumption Warning</strong> window opens if amounts differ. This is the default for a new BoM.</td></tr><tr><td><strong>Blocked</strong></td><td>The same window opens. Use it for recipes where amounts should not change.</td></tr></tbody></table><h2 id="produce-all" tabindex="-1">Produce All <a class="header-anchor" href="#produce-all" aria-label="Permalink to &quot;Produce All&quot;">​</a></h2><p>Scenario: finish <strong>MO/2</strong>, 2 Business Laptops, with nothing changed.</p><ol><li>Open <strong>MO/2</strong>. Its state is <strong>Confirmed</strong> or <strong>In Progress</strong>.</li><li>Check <strong>Quantity Producing</strong>. It equals the order quantity, 2.</li></ol>',10)),a(n,{src:"/images1/manufacturing/prod_quantity_producing.png",alt:"MO view or edit with Quantity Producing showing 2.0000 / 2.0000 Units and the Produce All button visible"}),t[1]||(t[1]=e("ol",{start:"3"},[e("li",null,[o("Click "),e("strong",null,"Produce All"),o(".")])],-1)),a(n,{src:"/images1/manufacturing/prod_produce_all.png",alt:"MO header with the Produce All button highlighted"}),t[2]||(t[2]=e("ol",{start:"4"},[e("li",null,[o("Aureus shows "),e("strong",null,"Manufacturing order completed"),o(". The state becomes "),e("strong",null,"Done"),o(".")])],-1)),a(n,{src:"/images1/manufacturing/prod_done.png",alt:"MO in Done state with state bar on Done and no action buttons"}),t[3]||(t[3]=r(`<h3 id="what-happens" tabindex="-1">What happens <a class="header-anchor" href="#what-happens" aria-label="Permalink to &quot;What happens&quot;">​</a></h3><ul><li>Open work orders are finished.</li><li>Components are consumed.</li><li>The finished goods are created.</li><li>The MO is locked. No action buttons remain.</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Stock → Pre-Production → Production        (components used up)</span></span>
<span class="line"><span>Production → Stock                         (finished laptops)</span></span></code></pre></div><p>With a three step warehouse, a store transfer (prefix <strong>SFP</strong>) also moves the finished goods to <strong>Stock</strong>. See <a href="./../basic-setup/three-step-manufacturing.html">Three step manufacturing</a>.</p><h2 id="produce-a-different-quantity" tabindex="-1">Produce a different quantity <a class="header-anchor" href="#produce-a-different-quantity" aria-label="Permalink to &quot;Produce a different quantity&quot;">​</a></h2><p>Change <strong>Quantity Producing</strong> to a number below or above the order quantity. The button label changes from <strong>Produce All</strong> to <strong>Produce</strong>.</p><ol><li>Open the MO and click <strong>Edit</strong>.</li><li>Set <strong>Quantity Producing</strong> to 1 and save.</li></ol>`,7)),a(n,{src:"/images1/manufacturing/prod_quantity_partial.png",alt:"MO edit form with Quantity Producing set to 1 of 2 and the Produce button showing"}),t[4]||(t[4]=e("ol",{start:"3"},[e("li",null,[o("Click "),e("strong",null,"Produce"),o(". Aureus asks you to confirm with "),e("strong",null,"Submit"),o(" or "),e("strong",null,"Cancel"),o(".")])],-1)),t[5]||(t[5]=e("p",null,[o("The window is titled "),e("strong",null,"Produced is different than expected"),o('. It says: "The quantity produced is different than expected. Do you want to confirm the manufacturing order with the current quantity?"')],-1)),a(n,{src:"/images1/manufacturing/prod_produced_warning.png",alt:"Produced is different than expected modal on an MO with Quantity Producing 1 of 2"}),t[6]||(t[6]=r('<p>Click <strong>Submit</strong>. The order completes with the quantity you entered.</p><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Result</th></tr></thead><tbody><tr><td><strong>Produce All</strong></td><td>Finishes the full quantity. State <strong>Done</strong>.</td></tr><tr><td><strong>Produce</strong></td><td>Finishes the quantity in <strong>Quantity Producing</strong>. The order completes. State <strong>Done</strong>.</td></tr></tbody></table><p>A <strong>Done</strong> order is locked. To start again, create a new MO.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./manufacturing-orders.html">Manufacturing orders</a></li><li><a href="./work-orders.html">Work orders</a></li><li><a href="./lots-and-serial-numbers.html">Lots and serial numbers</a></li><li><a href="./../basic-setup/bill-of-materials.html">Bill of materials</a></li></ul>',6))])}const w=s(l,[["render",c]]);export{P as __pageData,w as default};
